tap.service:
[[[
  const ventStates = [
    states['cover.great_room_edc5_vent']?.state,
    states['cover.great_room_large_b09b_vent']?.state
  ];
  return ventStates.some((state) => state === 'open' || state === 'opening')
    ? 'cover.close_cover_tilt'
    : 'cover.open_cover_tilt';
]]]
